/*
 * Probe FMU: FMI 2.0 Co-Simulation FMU tracing every FMI call it receives.
 *
 * Internal tool of the importer comparison study (docs/local/importer_comparison.md). One source for the three
 * probes Probe10ms, Probe20ms and Probe50ms: probe_config.h (generated by make_probe.py) gives the GUID and the
 * step size of each one.
 *
 * The trace is a CSV file, one line per FMI call (and one per value for fmi2Get*, fmi2Set* and the inputs seen by
 * fmi2DoStep), plus snapshots of every variable around the initialization. See README.md.
 */
#if !defined(_WIN32) && !defined(_POSIX_C_SOURCE)
#define _POSIX_C_SOURCE 200809L     /* clock_gettime, nanosleep, snprintf */
#endif

#include <math.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _WIN32
#include <windows.h>
#else
#include <time.h>
#endif

#include "fmi2Functions.h"
#include "probe_config.h"


/*----------------------------------------------------------------------------
                               V A R I A B L E S
----------------------------------------------------------------------------*/

typedef enum { VR_P_REAL = 0, VR_P_TUNABLE = 1, VR_COMPUTE_TIME = 2, VR_COMPUTE_SLEEP = 3, VR_STRICT_STEP = 4,
               VR_TRACE_FILE = 5,
               VR_U_CONT = 10, VR_U_DISC = 11, VR_U_INT = 12, VR_U_BOOL = 13,
               VR_Y_CONT = 20, VR_Y_DISC = 21, VR_Y_INT = 22, VR_Y_BOOL = 23, VR_Y_INIT = 24, VR_Y_TIME = 25 } vr_t;

typedef enum { TYPE_REAL, TYPE_INTEGER, TYPE_BOOLEAN, TYPE_STRING } var_type_t;

typedef enum { KIND_FIXED, KIND_TUNABLE, KIND_INPUT, KIND_OUTPUT } var_kind_t;

typedef struct {
    fmi2ValueReference vr;
    const char *name;
    var_type_t type;
    var_kind_t kind;
} variable_t;

static const variable_t VARIABLES[] = {
    { VR_P_REAL,        "p_real",        TYPE_REAL,    KIND_FIXED   },
    { VR_P_TUNABLE,     "p_tunable",     TYPE_REAL,    KIND_TUNABLE },
    { VR_COMPUTE_TIME,  "compute_time",  TYPE_REAL,    KIND_FIXED   },
    { VR_COMPUTE_SLEEP, "compute_sleep", TYPE_BOOLEAN, KIND_FIXED   },
    { VR_STRICT_STEP,   "strict_step",   TYPE_BOOLEAN, KIND_FIXED   },
    { VR_TRACE_FILE,    "trace_file",    TYPE_STRING,  KIND_FIXED   },
    { VR_U_CONT,        "u_cont",        TYPE_REAL,    KIND_INPUT   },
    { VR_U_DISC,        "u_disc",        TYPE_REAL,    KIND_INPUT   },
    { VR_U_INT,         "u_int",         TYPE_INTEGER, KIND_INPUT   },
    { VR_U_BOOL,        "u_bool",        TYPE_BOOLEAN, KIND_INPUT   },
    { VR_Y_CONT,        "y_cont",        TYPE_REAL,    KIND_OUTPUT  },
    { VR_Y_DISC,        "y_disc",        TYPE_REAL,    KIND_OUTPUT  },
    { VR_Y_INT,         "y_int",         TYPE_INTEGER, KIND_OUTPUT  },
    { VR_Y_BOOL,        "y_bool",        TYPE_BOOLEAN, KIND_OUTPUT  },
    { VR_Y_INIT,        "y_init",        TYPE_REAL,    KIND_OUTPUT  },
    { VR_Y_TIME,        "y_time",        TYPE_REAL,    KIND_OUTPUT  },
};
#define NB_VARIABLES (sizeof(VARIABLES) / sizeof(VARIABLES[0]))

static const variable_t *find_variable(fmi2ValueReference vr) {
    for (size_t i = 0; i < NB_VARIABLES; i += 1)
        if (VARIABLES[i].vr == vr)
            return &VARIABLES[i];
    return NULL;
}


/*----------------------------------------------------------------------------
                               I N S T A N C E
----------------------------------------------------------------------------*/

typedef enum { STATE_INSTANTIATED, STATE_INITIALIZATION, STATE_STEP, STATE_TERMINATED } state_t;

typedef struct {
    /* FMI */
    char *instance_name;
    fmi2CallbackLogger logger;
    fmi2ComponentEnvironment environment;
    int logging_on;
    state_t state;
    double time;

    /* Parameters */
    double p_real;
    double p_tunable;
    double compute_time;
    int compute_sleep;
    int strict_step;
    char *trace_file;

    /* Inputs */
    double u_cont;
    double u_disc;
    int u_int;
    int u_bool;

    /* Internal values of the outputs */
    double latched_u_disc;
    int latched_u_int;
    int latched_u_bool;
    double y_init;
    int nb_steps;

    /* Trace */
    FILE *trace;
    int trace_failed;
    char *buffer;           /* lines written before the trace file is opened */
    size_t buffer_length;
    size_t buffer_size;
    unsigned long seq;
    double wall_start;
    double wall;            /* wall clock of the current call */
} probe_t;


static double wall_clock(void) {
#ifdef _WIN32
    LARGE_INTEGER frequency, counter;
    QueryPerformanceFrequency(&frequency);
    QueryPerformanceCounter(&counter);
    return (double)counter.QuadPart / (double)frequency.QuadPart;
#else
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (double)now.tv_sec + (double)now.tv_nsec * 1e-9;
#endif
}


static void wait_for(double duration, int sleep) {
    if (duration <= 0.0)
        return;
    if (sleep) {
#ifdef _WIN32
        Sleep((DWORD)(duration * 1000.0 + 0.5));
#else
        struct timespec delay;
        delay.tv_sec = (time_t)duration;
        delay.tv_nsec = (long)((duration - (double)delay.tv_sec) * 1e9);
        nanosleep(&delay, NULL);
#endif
    } else {
        const double end = wall_clock() + duration;
        while (wall_clock() < end)
            ;
    }
}


static char *duplicate(const char *text) {
    if (!text)
        text = "";
    char *copy = malloc(strlen(text) + 1);
    if (copy)
        strcpy(copy, text);
    return copy;
}


static void set_start_values(probe_t *probe) {
    probe->time = 0.0;
    probe->p_real = 1.0;
    probe->p_tunable = 0.0;
    probe->compute_time = 0.0;
    probe->compute_sleep = 0;
    probe->strict_step = 0;
    free(probe->trace_file);
    probe->trace_file = duplicate("");
    probe->u_cont = 0.0;
    probe->u_disc = 0.0;
    probe->u_int = 0;
    probe->u_bool = 0;
    probe->latched_u_disc = 0.0;
    probe->latched_u_int = 0;
    probe->latched_u_bool = 0;
    probe->y_init = 0.0;
    probe->nb_steps = 0;
}


/*----------------------------------------------------------------------------
                                  L O G G E R
----------------------------------------------------------------------------*/

static void log_message(const probe_t *probe, fmi2Status status, const char *category, const char *format, ...) {
    if (!probe->logger)
        return;
    char message[1024];
    va_list args;
    va_start(args, format);
    vsnprintf(message, sizeof(message), format, args);
    va_end(args);
    /* The message is given as a format: '%' must not be interpreted again by the importer. */
    probe->logger(probe->environment, probe->instance_name, status, category, "%s", message);
}


/*----------------------------------------------------------------------------
                                   T R A C E
----------------------------------------------------------------------------*/

static const char *status_name(fmi2Status status) {
    switch (status) {
        case fmi2OK:      return "OK";
        case fmi2Warning: return "Warning";
        case fmi2Discard: return "Discard";
        case fmi2Error:   return "Error";
        case fmi2Fatal:   return "Fatal";
        case fmi2Pending: return "Pending";
    }
    return "?";
}


static void buffer_append(probe_t *probe, const char *text) {
    const size_t length = strlen(text);
    if (probe->buffer_length + length + 1 > probe->buffer_size) {
        size_t size = probe->buffer_size ? probe->buffer_size * 2 : 4096;
        while (size < probe->buffer_length + length + 1)
            size *= 2;
        char *buffer = realloc(probe->buffer, size);
        if (!buffer)
            return;
        probe->buffer = buffer;
        probe->buffer_size = size;
    }
    memcpy(probe->buffer + probe->buffer_length, text, length + 1);
    probe->buffer_length += length;
}


/* CSV field: quoted when it holds a comma, a quote or a line break. */
static void csv_field(char *destination, size_t size, const char *text) {
    if (!strpbrk(text, ",\"\r\n")) {
        snprintf(destination, size, "%s", text);
        return;
    }
    size_t j = 0;
    if (j + 1 < size)
        destination[j++] = '"';
    for (const char *c = text; *c && j + 3 < size; c += 1) {
        if (*c == '"')
            destination[j++] = '"';
        destination[j++] = *c;
    }
    if (j + 1 < size)
        destination[j++] = '"';
    destination[j] = '\0';
}


/* One line of the trace. `h` < 0: no step size; `variable` NULL: no value. */
static void trace_line(probe_t *probe, const char *function, fmi2Status status, double h,
                       const variable_t *variable, const char *value, const char *note) {
    char h_text[32] = "";
    char vr_text[16] = "";
    char value_field[1024];
    char note_field[512];
    char line[2048];

    if (h >= 0.0)
        snprintf(h_text, sizeof(h_text), "%.17g", h);
    if (variable)
        snprintf(vr_text, sizeof(vr_text), "%u", (unsigned)variable->vr);
    csv_field(value_field, sizeof(value_field), value ? value : "");
    csv_field(note_field, sizeof(note_field), note ? note : "");
    snprintf(line, sizeof(line), "%lu,%.6f,%s,%s,%.17g,%s,%s,%s,%s,%s\n", probe->seq,
             probe->wall - probe->wall_start, function, status_name(status), probe->time, h_text, vr_text,
             variable ? variable->name : "", value_field, note_field);

    if (probe->trace) {
        fputs(line, probe->trace);
        fflush(probe->trace);
    } else if (!probe->trace_failed) {
        buffer_append(probe, line);
    }
    if (probe->logging_on) {
        line[strlen(line) - 1] = '\0';
        log_message(probe, fmi2OK, "probe", "%s", line);
    }
}


/* Name of the default trace file: the instance name with the characters unsafe in a file name replaced. */
static char *default_trace_file(const probe_t *probe) {
    char *name = malloc(strlen(probe->instance_name) + 5);
    if (!name)
        return NULL;
    size_t i = 0;
    for (const char *c = probe->instance_name; *c; c += 1)
        name[i++] = strchr("<>:\"/\\|?* ", *c) ? '_' : *c;
    strcpy(name + i, ".csv");
    return name;
}


static fmi2Status trace_open(probe_t *probe) {
    if (probe->trace || probe->trace_failed)
        return fmi2OK;

    char *path = probe->trace_file[0] ? duplicate(probe->trace_file) : default_trace_file(probe);
    probe->trace = path ? fopen(path, "w") : NULL;
    if (!probe->trace) {
        probe->trace_failed = 1;
        log_message(probe, fmi2Error, "logStatusError", "Cannot open the trace file '%s'.", path ? path : "");
        free(path);
        free(probe->buffer);
        probe->buffer = NULL;
        return fmi2Error;
    }
    fputs("seq,wall,function,status,time,h,vr,name,value,note\n", probe->trace);
    if (probe->buffer)
        fputs(probe->buffer, probe->trace);
    fflush(probe->trace);
    free(probe->buffer);
    probe->buffer = NULL;
    free(path);
    return fmi2OK;
}


/*----------------------------------------------------------------------------
                                  V A L U E S
----------------------------------------------------------------------------*/

static double get_real(const probe_t *probe, fmi2ValueReference vr) {
    switch (vr) {
        case VR_P_REAL:       return probe->p_real;
        case VR_P_TUNABLE:    return probe->p_tunable;
        case VR_COMPUTE_TIME: return probe->compute_time;
        case VR_U_CONT:       return probe->u_cont;
        case VR_U_DISC:       return probe->u_disc;
        case VR_Y_CONT:       return probe->u_cont + probe->p_tunable;
        case VR_Y_DISC:       return probe->latched_u_disc;
        case VR_Y_INIT:       /* computed until the end of the initialization, then frozen */
            return probe->state == STATE_INSTANTIATED || probe->state == STATE_INITIALIZATION ?
                   probe->p_real + probe->u_cont : probe->y_init;
        case VR_Y_TIME:       return probe->time;
        default:              return 0.0;
    }
}


static int get_integer(const probe_t *probe, fmi2ValueReference vr) {
    switch (vr) {
        case VR_U_INT: return probe->u_int;
        case VR_Y_INT: return probe->nb_steps + 1000 * probe->latched_u_int;
        default:       return 0;
    }
}


static int get_boolean(const probe_t *probe, fmi2ValueReference vr) {
    switch (vr) {
        case VR_COMPUTE_SLEEP: return probe->compute_sleep;
        case VR_STRICT_STEP:   return probe->strict_step;
        case VR_U_BOOL:        return probe->u_bool;
        case VR_Y_BOOL:        return probe->latched_u_bool;
        default:               return 0;
    }
}


static void value_text(const probe_t *probe, const variable_t *variable, char *text, size_t size) {
    switch (variable->type) {
        case TYPE_REAL:    snprintf(text, size, "%.17g", get_real(probe, variable->vr)); break;
        case TYPE_INTEGER: snprintf(text, size, "%d", get_integer(probe, variable->vr)); break;
        case TYPE_BOOLEAN: snprintf(text, size, "%s", get_boolean(probe, variable->vr) ? "true" : "false"); break;
        case TYPE_STRING:  snprintf(text, size, "%s", probe->trace_file); break;
    }
}


static void snapshot(probe_t *probe, const char *label) {
    char text[1024];
    for (size_t i = 0; i < NB_VARIABLES; i += 1) {
        value_text(probe, &VARIABLES[i], text, sizeof(text));
        trace_line(probe, "SNAPSHOT", fmi2OK, -1.0, &VARIABLES[i], text, label);
    }
}


/* Checks a value reference of a fmi2Get* (set = 0) or fmi2Set* (set = 1) call. NULL if valid, else the reason. */
static const char *check_access(const probe_t *probe, fmi2ValueReference vr, var_type_t type, int set) {
    const variable_t *variable = find_variable(vr);
    if (!variable)
        return "unknown value reference";
    if (variable->type != type)
        return "wrong type";
    if (!set)
        return NULL;
    if (variable->kind == KIND_OUTPUT)
        return "output cannot be set";
    if (variable->kind == KIND_FIXED && probe->state != STATE_INSTANTIATED && probe->state != STATE_INITIALIZATION)
        return "fixed parameter cannot be set after the initialization";
    return NULL;
}


/* Validation pass shared by the getters and setters: the status of the call and the reason of each refused VR. */
static fmi2Status check_accesses(probe_t *probe, const char *function, const fmi2ValueReference vr[], size_t nvr,
                                 var_type_t type, int set) {
    fmi2Status status = fmi2OK;
    for (size_t i = 0; i < nvr; i += 1) {
        const char *reason = check_access(probe, vr[i], type, set);
        if (reason) {
            status = fmi2Error;
            log_message(probe, fmi2Error, "logStatusError", "%s: vr=%u: %s.", function, (unsigned)vr[i], reason);
        }
    }
    return status;
}


static void trace_accesses(probe_t *probe, const char *function, fmi2Status status,
                           const fmi2ValueReference vr[], size_t nvr, var_type_t type, int set) {
    char text[1024];
    if (nvr == 0)
        trace_line(probe, function, status, -1.0, NULL, NULL, "nvr=0");
    for (size_t i = 0; i < nvr; i += 1) {
        const char *reason = check_access(probe, vr[i], type, set);
        const variable_t *variable = find_variable(vr[i]);
        if (reason || !variable) {
            char note[128];
            snprintf(note, sizeof(note), "vr=%u: %s", (unsigned)vr[i], reason ? reason : "");
            trace_line(probe, function, status, -1.0, NULL, NULL, note);
        } else {
            value_text(probe, variable, text, sizeof(text));
            trace_line(probe, function, status, -1.0, variable, text, NULL);
        }
    }
}


static probe_t *begin_call(fmi2Component c) {
    probe_t *probe = (probe_t *)c;
    if (probe) {
        probe->seq += 1;
        probe->wall = wall_clock();
    }
    return probe;
}


/*----------------------------------------------------------------------------
                       F M I   2 . 0   F U N C T I O N S
----------------------------------------------------------------------------*/

const char *fmi2GetTypesPlatform(void) {
    return fmi2TypesPlatform;
}


const char *fmi2GetVersion(void) {
    return fmi2Version;
}


fmi2Status fmi2SetDebugLogging(fmi2Component c, fmi2Boolean loggingOn, size_t nCategories,
                               const fmi2String categories[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    probe->logging_on = loggingOn ? 1 : 0;

    char note[512] = "";
    for (size_t i = 0; i < nCategories; i += 1) {
        const size_t length = strlen(note);
        snprintf(note + length, sizeof(note) - length, "%s%s", i ? " " : "", categories[i]);
    }
    trace_line(probe, "fmi2SetDebugLogging", fmi2OK, -1.0, NULL, loggingOn ? "true" : "false", note);
    return fmi2OK;
}


fmi2Component fmi2Instantiate(fmi2String instanceName, fmi2Type fmuType, fmi2String fmuGUID,
                              fmi2String fmuResourceLocation, const fmi2CallbackFunctions *functions,
                              fmi2Boolean visible, fmi2Boolean loggingOn) {
    (void)fmuResourceLocation;
    (void)visible;

    probe_t *probe = calloc(1, sizeof(probe_t));
    if (!probe)
        return NULL;
    probe->instance_name = duplicate(instanceName);
    probe->logger = functions ? functions->logger : NULL;
    probe->environment = functions ? functions->componentEnvironment : NULL;
    probe->logging_on = loggingOn ? 1 : 0;
    probe->state = STATE_INSTANTIATED;
    probe->wall_start = wall_clock();
    set_start_values(probe);
    begin_call(probe);

    if (fmuType != fmi2CoSimulation || !fmuGUID || strcmp(fmuGUID, PROBE_GUID) != 0) {
        log_message(probe, fmi2Error, "logStatusError", "fmi2Instantiate: %s.",
                    fmuType != fmi2CoSimulation ? "only Co-Simulation is supported" : "wrong GUID");
        free(probe->instance_name);
        free(probe->trace_file);
        free(probe);
        return NULL;
    }

    char note[64];
    snprintf(note, sizeof(note), "model=%s step_size=%.17g", PROBE_MODEL_NAME, PROBE_STEP_SIZE);
    trace_line(probe, "fmi2Instantiate", fmi2OK, -1.0, NULL, instanceName, note);
    return probe;
}


void fmi2FreeInstance(fmi2Component c) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return;
    trace_line(probe, "fmi2FreeInstance", fmi2OK, -1.0, NULL, NULL, NULL);
    trace_open(probe);      /* initialization never reached: the buffered lines are written anyway */
    if (probe->trace)
        fclose(probe->trace);
    free(probe->buffer);
    free(probe->trace_file);
    free(probe->instance_name);
    free(probe);
}


fmi2Status fmi2SetupExperiment(fmi2Component c, fmi2Boolean toleranceDefined, fmi2Real tolerance,
                               fmi2Real startTime, fmi2Boolean stopTimeDefined, fmi2Real stopTime) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    snapshot(probe, "before_setup_experiment");
    probe->time = startTime;

    char note[160];
    snprintf(note, sizeof(note), "tolerance=%s stop_time=%s",
             toleranceDefined ? "defined" : "undefined", stopTimeDefined ? "defined" : "undefined");
    char value[160];
    snprintf(value, sizeof(value), "start=%.17g tolerance=%.17g stop=%.17g", startTime, tolerance, stopTime);
    trace_line(probe, "fmi2SetupExperiment", fmi2OK, -1.0, NULL, value, note);
    return fmi2OK;
}


fmi2Status fmi2EnterInitializationMode(fmi2Component c) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    snapshot(probe, "before_initialization");
    probe->state = STATE_INITIALIZATION;
    trace_line(probe, "fmi2EnterInitializationMode", fmi2OK, -1.0, NULL, NULL, NULL);
    return trace_open(probe);
}


fmi2Status fmi2ExitInitializationMode(fmi2Component c) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    probe->y_init = probe->p_real + probe->u_cont;
    probe->state = STATE_STEP;
    trace_line(probe, "fmi2ExitInitializationMode", fmi2OK, -1.0, NULL, NULL, NULL);
    snapshot(probe, "after_initialization");
    return fmi2OK;
}


fmi2Status fmi2Terminate(fmi2Component c) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    trace_line(probe, "fmi2Terminate", fmi2OK, -1.0, NULL, NULL, NULL);
    snapshot(probe, "terminate");
    probe->state = STATE_TERMINATED;
    return fmi2OK;
}


fmi2Status fmi2Reset(fmi2Component c) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    set_start_values(probe);
    probe->state = STATE_INSTANTIATED;
    trace_line(probe, "fmi2Reset", fmi2OK, -1.0, NULL, NULL, NULL);
    return fmi2OK;
}


/* Getters and setters */

fmi2Status fmi2GetReal(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, fmi2Real value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2GetReal", vr, nvr, TYPE_REAL, 0);
    for (size_t i = 0; i < nvr; i += 1)
        value[i] = get_real(probe, vr[i]);
    trace_accesses(probe, "fmi2GetReal", status, vr, nvr, TYPE_REAL, 0);
    return status;
}


fmi2Status fmi2GetInteger(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, fmi2Integer value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2GetInteger", vr, nvr, TYPE_INTEGER, 0);
    for (size_t i = 0; i < nvr; i += 1)
        value[i] = get_integer(probe, vr[i]);
    trace_accesses(probe, "fmi2GetInteger", status, vr, nvr, TYPE_INTEGER, 0);
    return status;
}


fmi2Status fmi2GetBoolean(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, fmi2Boolean value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2GetBoolean", vr, nvr, TYPE_BOOLEAN, 0);
    for (size_t i = 0; i < nvr; i += 1)
        value[i] = get_boolean(probe, vr[i]) ? fmi2True : fmi2False;
    trace_accesses(probe, "fmi2GetBoolean", status, vr, nvr, TYPE_BOOLEAN, 0);
    return status;
}


fmi2Status fmi2GetString(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, fmi2String value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2GetString", vr, nvr, TYPE_STRING, 0);
    for (size_t i = 0; i < nvr; i += 1)
        value[i] = vr[i] == VR_TRACE_FILE ? probe->trace_file : "";
    trace_accesses(probe, "fmi2GetString", status, vr, nvr, TYPE_STRING, 0);
    return status;
}


fmi2Status fmi2SetReal(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, const fmi2Real value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2SetReal", vr, nvr, TYPE_REAL, 1);
    if (status == fmi2OK) {
        for (size_t i = 0; i < nvr; i += 1) {
            switch (vr[i]) {
                case VR_P_REAL:       probe->p_real = value[i]; break;
                case VR_P_TUNABLE:    probe->p_tunable = value[i]; break;
                case VR_COMPUTE_TIME: probe->compute_time = value[i]; break;
                case VR_U_CONT:       probe->u_cont = value[i]; break;
                case VR_U_DISC:       probe->u_disc = value[i]; break;
                default:              break;
            }
        }
    }
    trace_accesses(probe, "fmi2SetReal", status, vr, nvr, TYPE_REAL, 1);
    return status;
}


fmi2Status fmi2SetInteger(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, const fmi2Integer value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2SetInteger", vr, nvr, TYPE_INTEGER, 1);
    if (status == fmi2OK) {
        for (size_t i = 0; i < nvr; i += 1)
            if (vr[i] == VR_U_INT)
                probe->u_int = value[i];
    }
    trace_accesses(probe, "fmi2SetInteger", status, vr, nvr, TYPE_INTEGER, 1);
    return status;
}


fmi2Status fmi2SetBoolean(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, const fmi2Boolean value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2SetBoolean", vr, nvr, TYPE_BOOLEAN, 1);
    if (status == fmi2OK) {
        for (size_t i = 0; i < nvr; i += 1) {
            switch (vr[i]) {
                case VR_COMPUTE_SLEEP: probe->compute_sleep = value[i] ? 1 : 0; break;
                case VR_STRICT_STEP:   probe->strict_step = value[i] ? 1 : 0; break;
                case VR_U_BOOL:        probe->u_bool = value[i] ? 1 : 0; break;
                default:               break;
            }
        }
    }
    trace_accesses(probe, "fmi2SetBoolean", status, vr, nvr, TYPE_BOOLEAN, 1);
    return status;
}


fmi2Status fmi2SetString(fmi2Component c, const fmi2ValueReference vr[], size_t nvr, const fmi2String value[]) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    const fmi2Status status = check_accesses(probe, "fmi2SetString", vr, nvr, TYPE_STRING, 1);
    if (status == fmi2OK) {
        for (size_t i = 0; i < nvr; i += 1) {
            if (vr[i] == VR_TRACE_FILE) {
                free(probe->trace_file);
                probe->trace_file = duplicate(value[i]);
            }
        }
    }
    trace_accesses(probe, "fmi2SetString", status, vr, nvr, TYPE_STRING, 1);
    return status;
}


/* Co-Simulation */

fmi2Status fmi2DoStep(fmi2Component c, fmi2Real currentCommunicationPoint, fmi2Real communicationStepSize,
                      fmi2Boolean noSetFMUStatePriorToCurrentPoint) {
    (void)noSetFMUStatePriorToCurrentPoint;
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;

    char note[160] = "";
    fmi2Status status = fmi2OK;
    const double h = communicationStepSize;
    if (fabs(currentCommunicationPoint - probe->time) > 1e-9 * fmax(1.0, fabs(probe->time))) {
        snprintf(note, sizeof(note), "currentCommunicationPoint=%.17g != time", currentCommunicationPoint);
    }
    if (fabs(h - PROBE_STEP_SIZE) > 1e-9 * PROBE_STEP_SIZE) {
        const size_t length = strlen(note);
        snprintf(note + length, sizeof(note) - length, "%sh != step_size", length ? " ; " : "");
        status = probe->strict_step ? fmi2Error : fmi2OK;
        log_message(probe, probe->strict_step ? fmi2Error : fmi2Warning,
                    probe->strict_step ? "logStatusError" : "logStatusWarning",
                    "fmi2DoStep: h=%.17g differs from the step size %.17g (time=%.17g).", h, PROBE_STEP_SIZE,
                    currentCommunicationPoint);
    }
    probe->time = currentCommunicationPoint;
    trace_line(probe, "fmi2DoStep", status, h, NULL, NULL, note[0] ? note : NULL);

    /* Inputs seen by this step */
    static const fmi2ValueReference inputs[] = { VR_U_CONT, VR_U_DISC, VR_U_INT, VR_U_BOOL };
    char text[64];
    for (size_t i = 0; i < sizeof(inputs) / sizeof(inputs[0]); i += 1) {
        const variable_t *variable = find_variable(inputs[i]);
        value_text(probe, variable, text, sizeof(text));
        trace_line(probe, "fmi2DoStep", status, h, variable, text, "input");
    }
    if (status != fmi2OK)
        return status;

    probe->latched_u_disc = probe->u_disc;
    probe->latched_u_int = probe->u_int;
    probe->latched_u_bool = probe->u_bool;
    wait_for(probe->compute_time, probe->compute_sleep);
    probe->time = currentCommunicationPoint + h;
    probe->nb_steps += 1;
    return fmi2OK;
}


/* Unsupported functions: traced, fmi2Error */

static fmi2Status unsupported(fmi2Component c, const char *function) {
    probe_t *probe = begin_call(c);
    if (!probe)
        return fmi2Error;
    log_message(probe, fmi2Error, "logStatusError", "%s is not supported.", function);
    trace_line(probe, function, fmi2Error, -1.0, NULL, NULL, "not supported");
    return fmi2Error;
}


